static uint8_t g_prog[32];
static uint8_t g_main[1000*ELEM_SIZE];
static uint8_t g_work[1<<20];

int main(void){
    setvbuf(stdout, NULL, _IONBF, 0);
    sha256_full(g_prog, g_sc, 121);
    size_t workcap = 1<<16;
    if (getenv("WV_WORK")) workcap = strtoul(getenv("WV_WORK"), NULL, 0);
    unsigned flags = 0x20801;
    if (getenv("WV_FLAGS")) flags = (unsigned)strtoul(getenv("WV_FLAGS"), NULL, 16);

    sv_stack st = { g_main, 0 };
    const uint8_t* wit[5]; uint32_t wl[5];
    wit[0]=NULL; wl[0]=0; wit[1]=NULL; wl[1]=0; wit[2]=NULL; wl[2]=0;
    wit[3]=g_sig; wl[3]=71; wit[4]=g_sc; wl[4]=121;
    for (int i = 0; i < 4; i++){
        uint8_t* rec = g_main + (size_t)i*ELEM_SIZE;
        memcpy(rec, &wl[i], 4);
        if (wl[i]) memcpy(rec + ELEM_DATA_OFF, wit[i], wl[i]);
        st.sp++;
    }
    struct sv_ctx ctx = { g_tx, sizeof g_tx, 0, g_work, (unsigned long)workcap, 0,0,0, 300000 };
    sv_get_locktime_context(g_tx, sizeof g_tx, 0, &ctx.tx_version, &ctx.tx_locktime, &ctx.in_sequence);
    /* prefix sweep: run script[0..cut) for every cut; deterministic single
     * process, same TLS state sequence on both arches; diff the two outputs */
    for (int cut = 1; cut <= 121; cut++){
        sv_stack st = { g_main, 0 };
        for (int i = 0; i < 4; i++){
            uint8_t* rec = g_main + (size_t)i*ELEM_SIZE;
            uint32_t wl = i==3 ? 71 : 0;
            memcpy(rec, &wl, 4);
            if (wl) memcpy(rec + ELEM_DATA_OFF, g_sig, 71);
            st.sp++;
        }
        struct sv_ctx ctx = { g_tx, sizeof g_tx, 0, g_work, (unsigned long)workcap, 0,0,0, 300000 };
        sv_get_locktime_context(g_tx, sizeof g_tx, 0, &ctx.tx_version, &ctx.tx_locktime, &ctx.in_sequence);
        int err = 0;
        int ok = sv_run_v(g_sc, (size_t)cut, &st, flags, &ctx, &err, 1, sv_checksig_witness_v0_export);
        fprintf(stderr, ".");
        printf("cut=%d ok=%d err=%d sp=%zu", cut, ok, err, st.sp);
        for (size_t i = 0; i < st.sp && i < 5; i++){
            const uint8_t* rec = g_main + i*ELEM_SIZE;
            uint32_t n; memcpy(&n, rec, 4);
            if (n > 520) n = 520;
            printf(" [%u:", n);
            for (uint32_t k = 0; k < n && k < 12; k++) printf("%02x", rec[ELEM_DATA_OFF+k]);
            printf("]");
        }
        printf("\n");
    }
    return 0;
}
